package io.knowledgebrain.notification;
import java.util.*;import java.time.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;import org.apache.kafka.clients.consumer.*;
import io.knowledgebrain.contracts.notification.inapp.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_NOTIFICATION_KAFKA_BOOTSTRAP",matches=".+")
class NotificationKafkaIntegrationTest {
 @Test void canonicalDeliveryReadAndArchiveOutboxReachOwnStreamWithImmutableOrigin()throws Exception{var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_NOTIFICATION_DATABASE_URL"));ds.setUser("brain_notification");ds.setPassword(System.getenv("BRAIN_TEST_NOTIFICATION_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var store=new NotificationStore(ds,Clock.systemUTC());var space=DispatchFixtures.ids.next();var actor=DispatchFixtures.ids.next();var source=DispatchFixtures.event(space,DispatchFixtures.ids.next());assertTrue(store.accept(source));var v=store.list(space,"ACTIVE","ALL",null,20).items().getFirst();store.change(space,v.notificationId(),actor,1,true,false,"b".repeat(32));store.change(space,v.notificationId(),actor,2,null,true,"b".repeat(32));assertFalse(store.accept(source));var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid=?",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),v.notificationId()).forEach(e->expected.put(e.getKey(),e.getValue()));assertEquals(3,expected.size());var p=NotificationConfiguration.kafka(System.getenv("BRAIN_TEST_NOTIFICATION_KAFKA_BOOTSTRAP"),"/notification-kafka-test","notification-validation-"+DispatchFixtures.ids.next());p.put("auto.offset.reset","earliest");
 try(var c=new KafkaConsumer<String,byte[]>(p)){c.subscribe(List.of("notification.in-app.v1"));var found=new HashSet<String>();long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<3&&System.nanoTime()<deadline)for(var row:c.poll(Duration.ofSeconds(1))){if(!row.key().equals(v.notificationId().toString()))continue;var e=InAppNotificationEnvelopeV1.parseFrom(row.value());assertArrayEquals(expected.get(e.getEventId()),row.value());assertEquals("notification-service",e.getProducer());assertEquals("Notification",e.getAggregateType());assertEquals(space.toString(),e.getSpaceId());var payload=InAppNotificationPayloadV1.parseFrom(e.getPayload());assertArrayEquals(source,payload.getSourceDispatchEnvelope().toByteArray());assertEquals(v.originEventId().toString(),payload.getSourceEventId());assertEquals(v.source().deliveryId().toString(),payload.getDispatchId());assertEquals(payload.getVersion()>1,e.getActorId().equals(actor.toString()));for(var h:Map.of("id",e.getEventId(),"trace_id",payload.getVersion()==1?"a".repeat(32):"b".repeat(32),"schema_group","notification","schema_artifact","in-app-events","schema_version","1").entrySet())assertEquals(h.getValue(),new String(row.headers().lastHeader(h.getKey()).value(),StandardCharsets.UTF_8));found.add(e.getEventId());}assertEquals(expected.keySet(),found);}
 }
}
